import React from "react";

class ChatPageItem extends React.Component {
    render() {
        const { text, is_me } = this.props;

        return (
            <div className={`d-flex ${is_me ? "justify-content-end" : "justify-content-start"} mb-3`}>
                
                <div
                    className={`chat-bubble boder ${
                        is_me ? "chat-bubble-me" : "chat-bubble-other"
                    }`}
                >
                    {text}
                </div>

            </div>
        );
    }
}

export default ChatPageItem;
